    e.preventDefault();if(!movementItem)return;setBusy(true);setError('')
    try { await api<InventoryMovement>(`/api/warehouses/${warehouseId}/stock/${movementItem.stockItemId}/transactions`,token,{method:'POST',body:JSON.stringify({entryDate,direction:movementDirection,quantity:Number(quantity),description,unitCostBase:movementDirection==='Receipt'&&unitCostBase?Number(unitCostBase):null})});setQuantity('');setDescription('');setUnitCostBase('');setNotice('Stok hareketi kaydedildi; çıkış maliyeti mevcut ağırlıklı ortalamadan hesaplandı.');await openMovements(movementItem);await loadBalances() }
    catch(e) { setError((e as Error).message) } finally { setBusy(false) }
